def("삼각비", "01", "삼각비의 값", SEC.뜻, "기본", (rng) => {
    const [p, q, r] = pick(rng, TRIPLES);
    const mode = intBetween(rng, 0, 2);
    // $\angle B=90^\circ$ — $\overline{BC}$ 가 $\angle A$ 의 대변, $\overline{AB}$ 가 이웃변.
    // mode 2($\tan A=\overline{BC}/\overline{AB}$)는 진분수여야 하므로 대변을 짧게 고정한다.
    const swap = mode === 2 ? false : rng() < 0.5;
    const bc = swap ? q : p;
    const ab = swap ? p : q;
    const [num, den] = red(mode === 1 ? ab : bc, mode === 2 ? ab : r);
    const asked = trigOf(mode, "A");
    const ratio = [
      `\\dfrac{\\overline{BC}}{\\overline{AC}}`,
      `\\dfrac{\\overline{AB}}{\\overline{AC}}`,
      `\\dfrac{\\overline{BC}}{\\overline{AB}}`,
    ][mode]!;
    const raw = [
      `\\dfrac{${bc}}{${r}}`,
      `\\dfrac{${ab}}{${r}}`,
      `\\dfrac{${bc}}{${ab}}`,
    ][mode]!;
    return {
      content: `직각삼각형 $ABC$에서 $\\angle B=90^\\circ$이고 $\\overline{AB}=${cm(ab)}$, $\\overline{BC}=${cm(bc)}$일 때, $${asked}$의 값을 구하시오.`,
      answer: `$${frac(num, den)}$`,
      solution: `피타고라스 정리에서 $\\overline{AC}=\\sqrt{${ab}^2+${bc}^2}=${r}\\,(\\mathrm{cm})$이다.\n따라서 $${asked}=${ratio}=${raw === frac(num, den) ? raw : `${raw}=${frac(num, den)}`}$이다.`,
      facts: { ab, bc, ac: r, mode, num, den },
      figureSpec: figRight({
        vert: ab,
        horz: bc,
        dims: { AB: dimCm(ab), BC: dimCm(bc) },
      }),
    };
  }),

def(
    "삼각비",
    "12",
    "사분원을 이용하여 삼각비의 값 구하기",
    SEC.값,
    "응용",
    (rng) => {
      const ang = intBetween(rng, 25, 65);
      const rad = ang * DEG;
      const s100 = Math.round(Math.sin(rad) * 100);
      const c100 = Math.round(Math.cos(rad) * 100);
      const t100 = Math.round(Math.tan(rad) * 100);
      const mode = intBetween(rng, 0, 4);
      const parts = [[s100], [c100], [t100], [s100, c100], [c100, t100]][mode]!;
      const x100 = parts.reduce((u, v) => u + v, 0);
      const asked = [
        `\\sin ${ang}^\\circ`,
        `\\cos ${ang}^\\circ`,
        `\\tan ${ang}^\\circ`,
        `\\sin ${ang}^\\circ+\\cos ${ang}^\\circ`,
        `\\cos ${ang}^\\circ+\\tan ${ang}^\\circ`,
      ][mode]!;
      const two = (v: number): string => (v / 100).toFixed(2);
      return {
        content: `반지름의 길이가 $1$인 사분원에서 $\\angle AOB=${ang}^\\circ$이다. 점 $B$에서 $\\overline{OA}$에 내린 수선의 발을 $H$라 하고, 점 $A$를 지나고 $\\overline{OA}$에 수직인 직선이 $\\overrightarrow{OB}$와 만나는 점을 $T$라 하자. $\\overline{BH}=${two(s100)}$, $\\overline{OH}=${two(c100)}$, $\\overline{AT}=${two(t100)}$일 때, $${asked}$의 값을 구하시오.`,
        answer: `$${two(x100)}$`,
        solution: `$\\overline{OB}=\\overline{OA}=1$이므로 $\\sin ${ang}^\\circ=\\dfrac{\\overline{BH}}{\\overline{OB}}=\\overline{BH}$, $\\cos ${ang}^\\circ=\\dfrac{\\overline{OH}}{\\overline{OB}}=\\overline{OH}$, $\\tan ${ang}^\\circ=\\dfrac{\\overline{AT}}{\\overline{OA}}=\\overline{AT}$이다.\n따라서 $${asked}=${two(x100)}$이다.`,
        facts: { ang, s100, c100, t100, mode, x100 },
        figureSpec: figQuadrant({ ang }),
      };
    },
  ),

def(
    "삼각비",
    "16",
    "삼각비의 표를 이용하여 삼각비의 값 구하기",
    SEC.값,
    "기본",
    (rng) => {
      const b = intBetween(rng, 30, 58);
      const fn = intBetween(rng, 0, 2);
      const table = [0, 1, 2].map((i) => tableValue(fn, b + i));
      const mode = intBetween(rng, 0, 2);
      const rows = [0, 1, 2]
        .map((i) => `$${trigText(fn, b + i)}=${table[i]!.toFixed(4)}$`)
        .join(", ");
      const head = `삼각비의 표에서 ${rows}이다.`;
      if (mode === 0) {
        return {
          // 소수 넷째 자리까지 적으므로 마지막에 읽는 숫자는 만 배 한 정수의 끝 자리다.
          content: `${head} 이때 $${FN_NAMES[fn]} x=${table[2]!.toFixed(4)}$${eulReul(Math.round(table[2]! * 10000))} 만족시키는 $x$의 크기를 구하시오.`,
          answer: `$${b + 2}^\\circ$`,
          solution: `표에서 값이 $${table[2]!.toFixed(4)}$인 각을 찾으면 $${b + 2}^\\circ$이다.\n따라서 $x=${b + 2}^\\circ$이다.`,
          facts: { b, fn, mode, target: b + 2, val: table[2]! },
          figureSpec: null,
        };
      }
      if (mode === 1) {
        const sum = Number((table[0]! + table[2]!).toFixed(4));
        return {
          content: `${head} 이때 $${trigText(fn, b)}+${trigText(fn, b + 2)}$의 값을 구하시오.`,
          answer: `$${sum.toFixed(4)}$`,
          solution: `표에서 $${trigText(fn, b)}=${table[0]!.toFixed(4)}$, $${trigText(fn, b + 2)}=${table[2]!.toFixed(4)}$이다.\n따라서 구하는 값은 $${table[0]!.toFixed(4)}+${table[2]!.toFixed(4)}=${sum.toFixed(4)}$이다.`,
          facts: { b, fn, mode, target: b, val: sum },
          figureSpec: null,
        };
      }
      // 차 — 큰 값에서 작은 값을 뺀다($\cos$ 는 각이 커질수록 작아진다).
      const hi = fn === 1 ? b : b + 2;
      const lo = fn === 1 ? b + 2 : b;
      const diff = Number((tableValue(fn, hi) - tableValue(fn, lo)).toFixed(4));
      return {
        content: `${head} 이때 $${trigText(fn, hi)}-${trigText(fn, lo)}$의 값을 구하시오.`,
        answer: `$${diff.toFixed(4)}$`,
        solution: `표에서 $${trigText(fn, hi)}=${tableValue(fn, hi).toFixed(4)}$, $${trigText(fn, lo)}=${tableValue(fn, lo).toFixed(4)}$이다.\n따라서 구하는 값은 $${tableValue(fn, hi).toFixed(4)}-${tableValue(fn, lo).toFixed(4)}=${diff.toFixed(4)}$이다.`,
        facts: { b, fn, mode, target: hi, val: diff },
        figureSpec: null,
      };
    },
  ),

