def(
    "삼각비의 활용",
    "01",
    "직각삼각형의 변의 길이 구하기",
    SEC.활용,
    "기본",
    (rng) =>
      attempt<Body>(200, () => {
        const theta = pick(rng, [30, 45, 60] as const);
        const g = pick(rng, [4, 6, 8, 10, 12, 16, 20] as const);
        const mode = intBetween(rng, 0, 1);
        const sinT = exact(0, theta)!;
        const cosT = exact(1, theta)!;
        const adj = surdMul(surd(g, 1, 1), cosT);
        const opp = surdMul(surd(g, 1, 1), sinT);
        if (mode === 0) {
          // (넓이) $=\dfrac{1}{2}\times\overline{AB}\times\overline{BC}$
          const area = surdMul(surdMul(adj, opp), surd(1, 1, 2));
          if (area.d !== 1) return null;
          return {
            content: `직각삼각형 $ABC$에서 $\\angle B=90^\\circ$, $\\angle A=${theta}^\\circ$이고 $\\overline{AC}=${cm(g)}$일 때, 직각삼각형 $ABC$의 넓이를 구하시오.`,
            answer: `$${cm2(surdText(area))}$`,
            solution: `$\\overline{AB}=${g}\\times\\cos ${theta}^\\circ=${surdText(adj)}\\,(\\mathrm{cm})$, $\\overline{BC}=${g}\\times\\sin ${theta}^\\circ=${surdText(opp)}\\,(\\mathrm{cm})$이다.\n따라서 (넓이)$=\\dfrac{1}{2}\\times${surdText(adj)}\\times${surdText(opp)}=${surdText(area)}\\,(\\mathrm{cm}^2)$이다.`,
            facts: nums({ theta, given: g, mode, an: area.n, ar: area.r }),
            figureSpec: figRight({
              vert: surdValue(adj),
              horz: surdValue(opp),
              angA: `${theta}°`,
              dims: { CA: dimCm(g) },
            }),
          };
        }
        // 둘레 — 유리항과 무리항을 따로 모은다($45^\circ$ 는 둘 다 $\sqrt{2}$ 라 합쳐진다).
        let c0 = g;
        let irr: Surd = { n: 0, r: 1, d: 1 };
        for (const s of [adj, opp]) {
          if (s.r === 1) {
            c0 += s.n / s.d;
            continue;
          }
          const t = surdAdd(irr, s);
          if (!t) return null;
          irr = t;
        }
        if (!Number.isInteger(c0)) return null;
        if (irr.n === 0 || irr.d !== 1) return null;
        return {
          content: `직각삼각형 $ABC$에서 $\\angle B=90^\\circ$, $\\angle A=${theta}^\\circ$이고 $\\overline{AC}=${cm(g)}$일 때, 직각삼각형 $ABC$의 둘레의 길이를 구하시오.`,
          answer: `$${lenText(c0, irr.n, irr.r, "cm")}$`,
          solution: `$\\overline{AB}=${g}\\times\\cos ${theta}^\\circ=${surdText(adj)}\\,(\\mathrm{cm})$, $\\overline{BC}=${g}\\times\\sin ${theta}^\\circ=${surdText(opp)}\\,(\\mathrm{cm})$이다.\n따라서 (둘레)$=${g}+${surdText(adj)}+${surdText(opp)}=${binomText(c0, irr.n, irr.r)}\\,(\\mathrm{cm})$이다.`,
          facts: nums({ theta, given: g, mode, c0, c1: irr.n, root: irr.r }),
          figureSpec: figRight({
            vert: surdValue(adj),
            horz: surdValue(opp),
            angA: `${theta}°`,
            dims: { CA: dimCm(g) },
          }),
        };
      }),
  ),

def("삼각비", "08", "의 삼각비의 값", SEC.값, "기본", (rng) =>
    attempt(300, () => {
      const angles = [30, 45, 60] as const;
      const a1 = pick(rng, angles);
      const a2 = pick(rng, angles);
      const f1 = intBetween(rng, 0, 2);
      const f2 = intBetween(rng, 0, 2);
      if (a1 === a2 && f1 === f2) return null;
      const op = intBetween(rng, 0, 3);
      const v1 = exact(f1, a1);
      const v2 = exact(f2, a2);
      if (!v1 || !v2) return null;
      const res = applyOp(op, v1, v2);
      if (!res) return null;
      if (res.r === 1 && res.d > 1 && Math.abs(res.n) >= res.d) return null;
      const expr = `${trigText(f1, a1)} ${OP_TEXT[op]} ${trigText(f2, a2)}`;
      return {
        content: `$${expr}$의 값을 구하시오.`,
        answer: `$${surdText(res)}$`,
        solution: `$${trigText(f1, a1)}=${surdText(v1)}$, $${trigText(f2, a2)}=${surdText(v2)}$이다.\n따라서 $${expr}=${surdText(v1)} ${OP_TEXT[op]} ${surdText(v2)}=${surdText(res)}$이다.`,
        facts: { f1, a1, op, f2, a2, an: res.n, ar: res.r, ad: res.d },
        figureSpec: null,
      };
    }),
  ),

